\section{दुर्बलसमाधानानां सत्वस्य विशिष्टतायाश्च कृते प्रमाणस्य रूपरेखा}

वयं सुचारुसीमायाः सह परिबद्धक्षेत्रे $\Omega\subset\mathbb{R}^n$ रैखिक-दीर्घवृत्ताकार-सङ्कारकस्य कृते सीमा-मान-समस्यां विचारयामः:
\begin{equation}\label{eq:elliptic}
 -\Delta u + c u = f \quad\text{in }\Omega.
\end{equation}
अत्र $c\in L^\infty(\Omega)$ प्रायः सर्वत्र $c(x)\ge c_0>0$ सन्तुष्टं करोति, तथा च $f\in L^2(\Omega)$ अस्ति। दुर्बल-सूत्रीकरणं भवति: $u\in H^1_0(\Omega)$ तादृशं अन्वेषयन्तु येन
\[
a(u,v)=\int_\Omega (\nabla u\cdot\nabla v + c\,u v)\,dx = \int_\Omega f v\,dx,\qquad\forall v\in H^1_0(\Omega).
\]

\begin{theorem}[दुर्बलसमाधानानां विशिष्टता]\label{thm:uniqueness}
यदि $u\in H^1_0(\Omega)$ दुर्बलार्थे $f\equiv 0$ इत्यनेन सह \eqref{eq:elliptic} सन्तुष्टं करोति, तर्हि $u\equiv 0$ भवति।
\end{theorem}

\begin{proof}
मानक-ऊर्जा-विधिः प्रयुज्यते। मन्यामहे यत् $u$ समरूप-दुर्बल-समस्यां समाधत्ते तथा च $v=u$ इत्यनेन परीक्षणं करोति। बळान्वयस्य उपयोगेन वयं प्राप्नुमः
\begin{equation}\label{eq:coercive}
a(u,u)=\int_\Omega |\nabla u|^2 + c|u|^2\,dx \ge \min(1,c_0)\|u\|_{H^1_0(\Omega)}^2.
\end{equation}
यतः दक्षिणपक्षः शून्यः अस्ति, अतः \eqref{eq:coercive} इत्यनेन a.e. $u=0$ इति सूच्यते। एतेन विशिष्टतायाः तर्कः पूर्णः भवति।
\end{proof}

